def solve_a(n_max):
    a = [0] * (n_max + 1)
    a[1] = 0
    for n in range(2, n_max + 1):
        res = 0
        for i in range(1, n):
            val = a[i] + a[n-i] + min(i, n-i)
            if val > res:
                res = val
        a[n] = res
    return a

a_seq = solve_a(30)
for i in range(1, 31):
    print(f"a_{i} = {a_seq[i]}")

def solve_a_v2(n_max):
    a = [0] * (n_max + 1)
    a[1] = 0
    for n in range(2, n_max + 1):
        res = 0
        for i in range(1, (n // 2) + 1):
            val = a[i] + a[n - i] + i
            if val > res:
                res = val
        a[n] = res
    return a

a_seq = solve_a_v2(2025)
print(a_seq[2025])
